SELECT COUNT(*) FROM users as u, posts as p, postLinks as pl, votes as v WHERE u.Id = p.OwnerUserId AND p.Id = pl.RelatedPostId AND u.Id = v.UserId AND u.Views>=0 AND u.DownVotes>=0 AND u.CreationDate>='2010-08-04 16:59:53'::timestamp AND u.CreationDate<='2014-07-22 15:15:22'::timestamp AND p.CommentCount>=0 AND p.CommentCount<=13 AND v.CreationDate>='2010-07-19 00:00:00'::timestamp;